sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({ api, event, helpers, imports }) {
    console.log("Product in API:", api.state.clickedProduct);
    console.log("Category in API:", api.state.selectedCategory);

    // Retrieve the current state of clicked product and selected category
    var productSysId = api.state.clickedProduct.sys_id;
    var selectedCategory = api.state.selectedCategory;

    // Validate helpers.snHttp
    if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
        console.error("Error: helpers.snHttp is not properly initialized or callable.");
        return;
    }

    // Prepare the API request payload
    const requestData = {
        sys_id: productSysId,
        category: selectedCategory,
        flowName : "Automate Standard software Request"
    };

    try {
        // Make the HTTP POST request to update the table
        const response = await helpers.snHttp("/api/985627/publishtocatalogcustom", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(requestData)
        });

        console.log("Response:", response);

        if (response.status === 200 || response.response?.result?.status === "success") {
            console.log("Updated successfully in the table.");

            api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'positive',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Catalog published successfully'),
                        action: { type: 'dismiss' }
                    }
                ]
            });
            api.data.top_pro_from_top_pub_1.refresh();
        } else {
            console.error("Failed to save publisher", response);

            api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'critical',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Failed to Publish catalog'),
                        action: { type: 'dismiss' }
                    }
                ]
            });
        }
    } catch (httpError) {
        console.error("Error updating button in the table:", httpError);api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'critical',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Failed to Publish catalog'),
                        action: { type: 'dismiss' }
                    }
                ]
            });
    }
}
